import Foundation

public enum Language: String, CaseIterable, Identifiable {
    case spanish = "Spanish"
    case french = "French"
    case japanese = "Japanese"
    case german = "German"
    
    public var id: String { self.rawValue }
    
    public var flag: String {
        switch self {
        case .spanish: return "🇪🇸"
        case .french: return "🇫🇷"
        case .japanese: return "🇯🇵"
        case .german: return "🇩🇪"
        }
    }
    
    public var localeCode: String {
        switch self {
        case .spanish: return "es-ES"
        case .french: return "fr-FR"
        case .japanese: return "ja-JP"
        case .german: return "de-DE"
        }
    }
}

public enum DifficultyLevel: String, CaseIterable, Identifiable {
    case beginner = "Beginner"
    case intermediate = "Intermediate"
    case expert = "Expert"
    
    public var id: String { self.rawValue }
}

public struct Phrase: Identifiable, Hashable {
    public let id: UUID
    public let english: String
    public let translation: String
    public let romanization: String?
    public let exampleEnglish: String?
    public let exampleTranslation: String?
    
    public init(id: UUID = UUID(), english: String, translation: String, romanization: String? = nil, exampleEnglish: String? = nil, exampleTranslation: String? = nil) {
        self.id = id
        self.english = english
        self.translation = translation
        self.romanization = romanization
        self.exampleEnglish = exampleEnglish
        self.exampleTranslation = exampleTranslation
    }
}

public struct Unit: Identifiable, Hashable {
    public let id: UUID
    public let title: String
    public let description: String
    public let level: DifficultyLevel
    public let phrases: [Phrase]
    
    public init(id: UUID = UUID(), title: String, description: String, level: DifficultyLevel, phrases: [Phrase]) {
        self.id = id
        self.title = title
        self.description = description
        self.level = level
        self.phrases = phrases
    }
}

