                    Phrase(english: "Tracking number", translation: "追跡番号 (Tsuiseki bangou)", romanization: nil, exampleEnglish: "Can you tell me the tracking number?", exampleTranslation: "追跡番号を教えてもらえますか？"),
                    Phrase(english: "Where is Japan Post?", translation: "郵便局はどこですか？ (Yuubinkyoku wa doko desu ka?)", romanization: nil, exampleEnglish: "Excuse me, where is the post office?", exampleTranslation: "すみません、郵便局はどこですか？"),
                    Phrase(english: "I'd like to mail this letter", translation: "この手紙を出したいのですが (Kono tegami wo dashitai no desu ga)", romanization: nil, exampleEnglish: "I'd like to mail this letter to Spain.", exampleTranslation: "この手紙をスペインに出したいのですが (Kono tegami wo Supein ni dashitai no desu ga)"),
                    Phrase(english: "How long will it take?", translation: "どのくらいかかりますか (Dono kurai kakarimasu ka)", romanization: nil, exampleEnglish: "How long will it take to arrive?", exampleTranslation: "到着までどのくらいかかりますか (Touchaku made dono kurai kakarimasu ka)"),
                    Phrase(english: "I need to send a package", translation: "小包を送る必要があります (Kozutsumi wo okuru hitsuyou ga arimasu)", romanization: nil, exampleEnglish: "I need to send a package to the United States.", exampleTranslation: "アメリカに小包を送る必要があります (Amerika ni kozutsumi wo okuru hitsuyou ga arimasu)"),
                    Phrase(english: "Can I track it?", translation: "追跡できますか (Tsuiseki dekimasu ka)", romanization: nil, exampleEnglish: "Can I track the package online?", exampleTranslation: "小包をオンラインで追跡できますか (Kozutsumi wo onrain de tsuiseki dekimasu ka)")
                ]),
