                    Phrase(english: "I have an exam tomorrow", translation: "明日試験があります (Ashita shiken ga arimasu)", romanization: nil, exampleEnglish: "I have a math exam tomorrow morning.", exampleTranslation: "明日の朝、数学の試験があります (Ashita no asa, suugaku no shiken ga arimasu)"),
                    Phrase(english: "The homework was difficult", translation: "宿題は難しかったです (Shukudai wa muzukashikatta desu)", romanization: nil, exampleEnglish: "The homework yesterday was very difficult.", exampleTranslation: "昨日の宿題はとても難しかったです (Kinou no shukudai wa totemo muzukashikatta desu)"),
                    Phrase(english: "I need to go to the library", translation: "図書館に行く必要があります (Toshokan ni iku hitsuyou ga arimasu)", romanization: nil, exampleEnglish: "I need to go to the library to study.", exampleTranslation: "勉強するために図書館に行く必要があります (Benkyou suru tame ni toshokan ni iku hitsuyou ga arimasu)")
