                    Phrase(english: "Respect nature rules", translation: "自然のルールを守る (Shizen no ruuru o mamoru)", romanization: nil, exampleEnglish: "Please respect nature and take garbage home.", exampleTranslation: "自然のルールを守って、ゴミを持ち帰りましょう。"),
                    Phrase(english: "Look at that mountain", translation: "あの山を見て (Ano yama wo mite)", romanization: nil, exampleEnglish: "Look at that mountain, it's beautiful.", exampleTranslation: "あの山を見て、綺麗ですね (Ano yama wo mite, kirei desu ne)"),
                    Phrase(english: "The beach is very clean", translation: "ビーチはとても綺麗です (Biichi wa totemo kirei desu)", romanization: nil, exampleEnglish: "This beach is very clean and quiet.", exampleTranslation: "このビーチはとても綺麗で静かです (Kono biichi wa totemo kirei de shizuka desu)"),
                    Phrase(english: "There are many birds", translation: "たくさんの鳥がいます (Takusan no tori ga imasu)", romanization: nil, exampleEnglish: "There are many birds in this forest.", exampleTranslation: "この森にはたくさんの鳥がいます (Kono mori ni wa takusan no tori ga imasu)"),
                    Phrase(english: "The river is very wide", translation: "川はとても広いです (Kawa wa totemo hiroi desu)", romanization: nil, exampleEnglish: "The river is very wide here.", exampleTranslation: "ここの川はとても広いです (Koko no kawa wa totemo hiroi desu)")
                ]),
                Unit(title: "Arts, Kabuki & Culture", description: "Kabuki theater, tea ceremony (Sado), calligraphy (Shodo), traditional arts.", level: .intermediate, phrases: [
