                    Phrase(english: "Who is the artist?", translation: "作者は誰ですか (Sakusha wa dare desu ka)", romanization: nil, exampleEnglish: "Who is the artist of this sculpture?", exampleTranslation: "この彫刻の作者は誰ですか (Kono choukoku no sakusha wa dare desu ka)"),
                    Phrase(english: "The theater was full", translation: "劇場は満員でした (Gekijou wa manin deshita)", romanization: nil, exampleEnglish: "The theater was full last night.", exampleTranslation: "昨夜劇場は満員でした (Sakuya gekijou wa manin deshita)"),
                    Phrase(english: "It's a local tradition", translation: "地元の伝統です (Jimoto no dentou desu)", romanization: nil, exampleEnglish: "This festival is a local tradition.", exampleTranslation: "このお祭りは地元の伝統です (Kono omatsuri wa jimoto no dentou desu)")
                ]),
                Unit(title: "Festivals & Summer Matsuri", description: "Summer festivals (Matsuri), fireworks (Hanabi), Yukata, and food stalls (Yatai).", level: .intermediate, phrases: [
