                    Phrase(english: "Cheers!", translation: "乾杯 (Kanpai)", romanization: nil, exampleEnglish: "Cheers, to our friendship!", exampleTranslation: "乾杯、私たちの友情に (Kanpai, watashitachi no yuujou ni)"),
                    Phrase(english: "Let's celebrate", translation: "お祝いしましょう (Oiwai shimashou)", romanization: nil, exampleEnglish: "Let's celebrate your promotion.", exampleTranslation: "あなたの昇進をお祝いしましょう (Anata no shoushin wo oiwai shimashou)"),
