                ]),
                Unit(title: "Business Etiquette & Keigo", description: "Honorific Japanese (Sonkeigo/Kenjougo), business cards (Meishi exchange).", level: .expert, phrases: [
                    Phrase(english: "Exchange business cards", translation: "名刺交換 (Meishi koukan)", romanization: nil, exampleEnglish: "Please hold business card with both hands during exchange.", exampleTranslation: "名刺交換の際は両手で持ってください。"),
                    Phrase(english: "Thank you for taking time out of your busy schedule", translation: "お忙しいところありがとうございます (Oisogashii tokoro arigatou gozaimasu)", romanization: nil, exampleEnglish: "Thank you for meeting us today out of your busy schedule.", exampleTranslation: "本日はお忙しいところお時間をいただきありがとうございます。"),
