                ]),
                Unit(title: "Complaints & Politeness", description: "Address mistakes politely, express dissatisfaction without confrontation.", level: .intermediate, phrases: [
                    Phrase(english: "Excuse me, but there is a mistake", translation: "恐れ入りますが、間違いがあります (Osoreirimasu ga, machigai ga arimasu)", romanization: nil, exampleEnglish: "Excuse me, but there is a mistake on the receipt.", exampleTranslation: "恐れ入りますが、レシートに間違いがあります。"),
