                    Phrase(english: "I would like a return / exchange", translation: "返品・交換をお願いしたいです (Henpin/koukan o onegai shitai desu)", romanization: nil, exampleEnglish: "I would like an exchange with valid receipt.", exampleTranslation: "レシートがありますので、交換をお願いしたいです。"),
                    Phrase(english: "Thank you for resolving this smoothly", translation: "迅速なご対応ありがとうございます (Jinsoku na gotaiou arigatou gozaimasu)", romanization: nil, exampleEnglish: "Thank you for resolving this issue smoothly.", exampleTranslation: "迅速なご対応、ありがとうございます。"),
                    Phrase(english: "This is not what I ordered", translation: "これは注文したものではありません (Kore wa chuumon shita mono de wa arimasen)", romanization: nil, exampleEnglish: "Excuse me, this is not what I ordered.", exampleTranslation: "すみません、これは注文したものではありません (Sumimasen, kore wa chuumon shita mono de wa arimasen)"),
                    Phrase(english: "I'd like to speak with the manager", translation: "店長と話したいのですが (Tenchou to hanashitai no desu ga)", romanization: nil, exampleEnglish: "I'd like to speak with the manager, please.", exampleTranslation: "店長と話したいのですが、お願いします (Tenchou to hanashitai no desu ga, onegaishimasu)"),
                    Phrase(english: "I want a refund", translation: "返金してほしいです (Henkin shite hoshii desu)", romanization: nil, exampleEnglish: "The product is defective, I want a refund.", exampleTranslation: "商品に欠陥があるので、返金してほしいです (Shouhin ni kekkan ga aru node, henkin shite hoshii desu)"),
                    Phrase(english: "This is unacceptable", translation: "これは受け入れられません (Kore wa ukeireraremasen)", romanization: nil, exampleEnglish: "The delay is unacceptable.", exampleTranslation: "この遅延は受け入れられません (Kono chien wa ukeireraremasen)")
                ]),
