                    Phrase(english: "Is guarantor required?", translation: "保証人は必要ですか？ (Hoshounin wa hitsuyou desu ka?)", romanization: nil, exampleEnglish: "Is a Japanese guarantor required?", exampleTranslation: "保証人は必要ですか？"),
                    Phrase(english: "Monthly rent and maintenance fee", translation: "家賃と共益費 (Yachin to kyouekihi)", romanization: nil, exampleEnglish: "Rent is 80,000 yen and maintenance fee is 5,000 yen.", exampleTranslation: "家賃は8万円で、共益費は5千円です。"),
                    Phrase(english: "When can I move in?", translation: "いつから入居できますか？ (Itsu kara nyuukyo dekimasu ka?)", romanization: nil, exampleEnglish: "If contract signed, when can I move in?", exampleTranslation: "契約したら、いつから入居できますか？"),
                    Phrase(english: "How much is the rent?", translation: "家賃はいくらですか (Yachin wa ikura desu ka)", romanization: nil, exampleEnglish: "How much is the rent per month?", exampleTranslation: "月々の家賃はいくらですか (Tsukizuki no yachin wa ikura desu ka)"),
                    Phrase(english: "Are utilities included?", translation: "光熱費は含まれていますか (Kounetsuhi wa fukumarete imasu ka)", romanization: nil, exampleEnglish: "Are utilities included in the rent?", exampleTranslation: "家賃に光熱費は含まれていますか (Yachin ni kounetsuhi wa fukumarete imasu ka)"),
                    Phrase(english: "I'd like to sign the lease", translation: "賃貸契約にサインしたいのですが (Chintai keiyaku ni sain shitai no desu ga)", romanization: nil, exampleEnglish: "I'd like to sign the lease today.", exampleTranslation: "今日、賃貸契約にサインしたいのですが (Kyou, chintai keiyaku ni sain shitai no desu ga)"),
                    Phrase(english: "When can I move in?", translation: "いつ入居できますか (Itsu nyuukyo dekimasu ka)", romanization: nil, exampleEnglish: "When can I move in?", exampleTranslation: "いつ入居できますか (Itsu nyuukyo dekimasu ka)")
                ]),
                Unit(title: "Romance & Relationships", description: "Japanese confession (Kokuhaku), Suki desu, dating customs, and compliments.", level: .intermediate, phrases: [
