                    Phrase(english: "I really like you", translation: "あなたのことがとても好きです (Anata no koto ga totemo suki desu)", romanization: nil, exampleEnglish: "I really like you and want to see you again.", exampleTranslation: "あなたのことがとても好きで、また会いたいです (Anata no koto ga totemo suki de, mata aitai desu)"),
                    Phrase(english: "Would you like to have dinner?", translation: "夕食をご一緒しませんか (Yuushoku wo goissho shimasen ka)", romanization: nil, exampleEnglish: "Would you like to have dinner Friday night?", exampleTranslation: "金曜日の夜、夕食をご一緒しませんか (Kinyoubi no yoru, yuushoku wo goissho shimasen ka)"),
                    Phrase(english: "I miss you", translation: "あなたに会いたいです (Anata ni aitai desu)", romanization: nil, exampleEnglish: "I miss you a lot when you're away.", exampleTranslation: "あなたがいない時、とても会いたいです (Anata ga inai toki, totemo aitai desu)")
