                    Phrase(english: "Have you watched this J-Drama?", translation: "このドラマを見ましたか？ (Kono dorama o mimashita ka?)", romanization: nil, exampleEnglish: "Have you watched this popular Japanese drama?", exampleTranslation: "この人気のある日本のドラマを見ましたか？"),
                    Phrase(english: "I recommend this movie", translation: "この映画がおすすめです (Kono eiga ga osusume desu)", romanization: nil, exampleEnglish: "It is a masterpiece, I recommend this movie.", exampleTranslation: "名作です、この映画がおすすめです。"),
                    Phrase(english: "The live concert was moving", translation: "ライブコンサートが感動的でした (Raibu konsaato ga kandouteki deshita)", romanization: nil, exampleEnglish: "Yesterday the live concert was moving!", exampleTranslation: "昨日のライブコンサートがとても感動的でした！"),
                    Phrase(english: "Who is your favorite artist?", translation: "好きなアーティストは誰ですか？ (Suki na aatisuto wa dare desu ka?)", romanization: nil, exampleEnglish: "Who is your favorite Japanese musician?", exampleTranslation: "好きな日本のアーティストは誰ですか？"),
                    Phrase(english: "What kind of music do you like?", translation: "どんな音楽が好きですか (Donna ongaku ga suki desu ka)", romanization: nil, exampleEnglish: "What kind of music do you usually listen to?", exampleTranslation: "普段どんな音楽を聴きますか (Fudan donna ongaku wo kikimasu ka)"),
                    Phrase(english: "That series is amazing", translation: "あのドラマは素晴らしいです (Ano dorama wa subarashii desu)", romanization: nil, exampleEnglish: "That new series on Netflix is amazing.", exampleTranslation: "Netflixのあの新しいドラマは素晴らしいです (Netflix no ano atarashii dorama wa subarashii desu)"),
                    Phrase(english: "Who's your favorite actor?", translation: "好きな俳優は誰ですか (Suki na haiyuu wa dare desu ka)", romanization: nil, exampleEnglish: "Who's your favorite actor these days?", exampleTranslation: "最近好きな俳優は誰ですか (Saikin suki na haiyuu wa dare desu ka)"),
                    Phrase(english: "The movie was disappointing", translation: "映画はがっかりでした (Eiga wa gakkari deshita)", romanization: nil, exampleEnglish: "The last movie was really disappointing.", exampleTranslation: "最後の映画は本当にがっかりでした (Saigo no eiga wa hontou ni gakkari deshita)")
                ]),
                Unit(title: "Home Repairs & DIY", description: "Home maintenance, repair shops, electrical appliances, and tools.", level: .intermediate, phrases: [
                    Phrase(english: "Screwdriver and tools", translation: "ドライバーと工具 (Doraibaa to kougu)", romanization: nil, exampleEnglish: "I need a screwdriver and tools to assemble furniture.", exampleTranslation: "家具を組み立てるためにドライバーと工具が必要です。"),
                    Phrase(english: "The water pipe is leaking", translation: "水道管から水が漏れています (Suidoukan kara mizu ga morete imasu)", romanization: nil, exampleEnglish: "Call repairman, water pipe is leaking.", exampleTranslation: "修理業者を呼んでください、水道管から水が漏れています。"),
                    Phrase(english: "Light bulb replacement", translation: "電球の交換 (Denkyuu no koukan)", romanization: nil, exampleEnglish: "I need an LED light bulb replacement.", exampleTranslation: "LED電球の交換が必要です。"),
                    Phrase(english: "How do I repair this?", translation: "どうやって修理しますか？ (Dou yatte shuuri shimasu ka?)", romanization: nil, exampleEnglish: "Can you show me how to repair this drawer?", exampleTranslation: "この引き出しをどうやって修理しますか？"),
                    Phrase(english: "Power blackout", translation: "停電 (Teiden)", romanization: nil, exampleEnglish: "Because of typhoon, there is a power blackout.", exampleTranslation: "台風の影響で停電になりました。"),
                    Phrase(english: "Do you have a screwdriver?", translation: "ドライバーはありますか (Doraibaa wa arimasu ka)", romanization: nil, exampleEnglish: "Do you have a Phillips screwdriver?", exampleTranslation: "プラスドライバーはありますか (Purasu doraibaa wa arimasu ka)"),
                    Phrase(english: "I need to fix the sink", translation: "流し台を直す必要があります (Nagashidai wo naosu hitsuyou ga arimasu)", romanization: nil, exampleEnglish: "I need to fix the sink in the kitchen.", exampleTranslation: "キッチンの流し台を直す必要があります (Kitchin no nagashidai wo naosu hitsuyou ga arimasu)"),
                    Phrase(english: "The light isn't working", translation: "電気がつきません (Denki ga tsukimasen)", romanization: nil, exampleEnglish: "The light in the bathroom isn't working.", exampleTranslation: "浴室の電気がつきません (Yokushitsu no denki ga tsukimasen)"),
                    Phrase(english: "Can you recommend a plumber?", translation: "配管工を紹介してもらえますか (Haikankou wo shoukai shite moraemasu ka)", romanization: nil, exampleEnglish: "Can you recommend a good plumber?", exampleTranslation: "良い配管工を紹介してもらえますか (Yoi haikankou wo shoukai shite moraemasu ka)")
                ]),
                Unit(title: "Hair Salons & Grooming", description: "Haircut instructions at Japanese salons, hair dye, wash, and styling.", level: .beginner, phrases: [
                    Phrase(english: "Please trim just a little", translation: "少しだけ切ってください (Sukoshi dake kitte kudasai)", romanization: nil, exampleEnglish: "Don't cut too much, please trim just a little.", exampleTranslation: "切られすぎないで、少しだけ切ってください。"),
                    Phrase(english: "I'd like a haircut", translation: "カットをお願いします (Katto o onegai shimasu)", romanization: nil, exampleEnglish: "Hello, I'd like a haircut and shampoo, please.", exampleTranslation: "こんにちは、カットとシャンプーをお願いします。"),
                    Phrase(english: "Short on the sides", translation: "横は短めで (Yoko wa mijikame de)", romanization: nil, exampleEnglish: "Please make it short on the sides.", exampleTranslation: "横は短めでお願いします。"),
                    Phrase(english: "Can I make a salon reservation?", translation: "予約できますか？ (Yoyaku dekimasu ka?)", romanization: nil, exampleEnglish: "Can I make a salon reservation for tomorrow at 3 PM?", exampleTranslation: "明日15時に美容院の予約ができますか？"),
                    Phrase(english: "I really like this hairstyle!", translation: "この髪型がとても気に入りました！ (Kono kamigata ga totemo ki ni irimashita!)", romanization: nil, exampleEnglish: "Thank you, I really like this hairstyle!", exampleTranslation: "ありがとうございます、この髪型がとても気に入りました！"),
                    Phrase(english: "Just a trim, please", translation: "少しだけ切ってください (Sukoshi dake kitte kudasai)", romanization: nil, exampleEnglish: "Just a trim, please, not too short.", exampleTranslation: "少しだけ切ってください、短すぎないように (Sukoshi dake kitte kudasai, mijika suginai you ni)"),
                    Phrase(english: "I'd like a manicure", translation: "マニキュアをお願いします (Manikyua wo onegaishimasu)", romanization: nil, exampleEnglish: "I'd like a manicure and pedicure.", exampleTranslation: "マニキュアとペディキュアをお願いします (Manikyua to pedikyua wo onegaishimasu)"),
                    Phrase(english: "How long is the wait?", translation: "どれくらい待ちますか (Dore kurai machimasu ka)", romanization: nil, exampleEnglish: "How long is the wait for a haircut?", exampleTranslation: "カットはどれくらい待ちますか (Katto wa dore kurai machimasu ka)"),
                    Phrase(english: "Do I need an appointment?", translation: "予約は必要ですか (Yoyaku wa hitsuyou desu ka)", romanization: nil, exampleEnglish: "Do I need an appointment or can I walk in?", exampleTranslation: "予約は必要ですか、それとも直接来てもいいですか (Yoyaku wa hitsuyou desu ka, sore tomo chokusetsu kite mo ii desu ka)")
                ]),
                Unit(title: "Train Stations & Transfers", description: "Train platforms (Hoomu), transfer (Nori kae), express trains (Kyuko).", level: .intermediate, phrases: [
                    Phrase(english: "Where do I transfer for Yamanote line?", translation: "山手線への乗り換えはどこですか？ (Yamanotesen e no norikae wa doko desu ka?)", romanization: nil, exampleEnglish: "Excuse me, where do I transfer for Yamanote line?", exampleTranslation: "すみません、山手線への乗り換えはどこですか？"),
                    Phrase(english: "Is this a Rapid express train?", translation: "これは快速電車ですか？ (Kore wa kaisoku densha desu ka?)", romanization: nil, exampleEnglish: "Is this a Rapid express train or local train?", exampleTranslation: "これは快速電車ですか、それとも各駅停車ですか？"),
                    Phrase(english: "A round-trip train ticket", translation: "往復切符 (Oufuku kippu)", romanization: nil, exampleEnglish: "One round-trip train ticket to Kamakura, please.", exampleTranslation: "鎌倉までの往復切符を一枚お願いします。"),
                    Phrase(english: "Train delay announcement", translation: "電車の遅延 (Densha no chien)", romanization: nil, exampleEnglish: "Due to heavy rain, there is a train delay.", exampleTranslation: "大雨のため、電車の遅延が発生しています。"),
                    Phrase(english: "When is the last train (Shuden)?", translation: "終電は何時ですか？ (Shuden wa nanji desu ka?)", romanization: nil, exampleEnglish: "Don't miss it: when is the last train tonight?", exampleTranslation: "今夜の終電は何時ですか？"),
                    Phrase(english: "What platform does it leave from?", translation: "何番線から出発しますか (Nanbansen kara shuppatsu shimasu ka)", romanization: nil, exampleEnglish: "What platform does the train to Tokyo leave from?", exampleTranslation: "東京行きの電車は何番線から出発しますか (Toukyou yuki no densha wa nanbansen kara shuppatsu shimasu ka)"),
                    Phrase(english: "Is this the express train?", translation: "これは急行ですか (Kore wa kyuukou desu ka)", romanization: nil, exampleEnglish: "Excuse me, is this the express train?", exampleTranslation: "すみません、これは急行ですか (Sumimasen, kore wa kyuukou desu ka)"),
                    Phrase(english: "Round-trip ticket, please", translation: "往復切符をお願いします (Oufuku kippu wo onegaishimasu)", romanization: nil, exampleEnglish: "One round-trip ticket to Osaka, please.", exampleTranslation: "大阪までの往復切符を一枚お願いします (Oosaka made no oufuku kippu wo ichimai onegaishimasu)"),
                    Phrase(english: "Do I need to change trains?", translation: "乗り換えは必要ですか (Norikae wa hitsuyou desu ka)", romanization: nil, exampleEnglish: "Do I need to change trains to get there?", exampleTranslation: "そこに行くには乗り換えは必要ですか (Soko ni iku ni wa norikae wa hitsuyou desu ka)")
                ]),
                Unit(title: "Asking Deeper Questions", description: "Philosophical and analytical questions using ~Naze, ~Doushite, deep inquiry.", level: .expert, phrases: [
                    Phrase(english: "Why do you think so?", translation: "なぜそう思いますか？ (Naze sou omoimasu ka?)", romanization: nil, exampleEnglish: "Interesting perspective: why do you think so?", exampleTranslation: "興味深い見解ですね。なぜそう思いますか？"),
                    Phrase(english: "What led to this conclusion?", translation: "どのような経緯でその結論になりましたか？ (Dono you na keii de sono ketsuron ni narimashita ka?)", romanization: nil, exampleEnglish: "What led to this conclusion during analysis?", exampleTranslation: "どのような経緯でその結論になりましたか？"),
                    Phrase(english: "How would you solve this issue?", translation: "どのようにこの問題を解決しますか？ (Dono you ni kono mondai o kaiketsu shimasu ka?)", romanization: nil, exampleEnglish: "If you were leader, how would you solve this issue?", exampleTranslation: "リーダーなら、どのようにこの問題を解決しますか？"),
                    Phrase(english: "What are the long-term effects?", translation: "長期的な影響は何ですか？ (Choukiteki na eikyou wa nan desu ka?)", romanization: nil, exampleEnglish: "We must analyze: what are the long-term effects?", exampleTranslation: "分析が必要です。長期的な影響は何ですか？"),
                    Phrase(english: "Could you explain in detail?", translation: "詳しく説明していただけますか？ (Kwashiku setsumei shite itadakemasu ka?)", romanization: nil, exampleEnglish: "Crucial point, could you explain in detail?", exampleTranslation: "重要な点です。詳しく説明していただけますか？"),
                    Phrase(english: "What made you decide that?", translation: "何がその決断につながりましたか (Nani ga sono ketsudan ni tsunagarimashita ka)", romanization: nil, exampleEnglish: "What made you decide to move here?", exampleTranslation: "何がここに引っ越すという決断につながりましたか (Nani ga koko ni hikkosu to iu ketsudan ni tsunagarimashita ka)"),
                    Phrase(english: "Could you elaborate?", translation: "もう少し詳しく教えてください (Mou sukoshi kuwashiku oshiete kudasai)", romanization: nil, exampleEnglish: "That's interesting — could you elaborate?", exampleTranslation: "興味深いです、もう少し詳しく教えてください (Kyoumibukai desu, mou sukoshi kuwashiku oshiete kudasai)"),
                    Phrase(english: "What's your reasoning?", translation: "その理由は何ですか (Sono riyuu wa nan desu ka)", romanization: nil, exampleEnglish: "I see, but what's your reasoning behind that?", exampleTranslation: "なるほど、その理由は何ですか (Naruhodo, sono riyuu wa nan desu ka)"),
                    Phrase(english: "How do you know that?", translation: "どうしてそれを知っていますか (Doushite sore wo shitte imasu ka)", romanization: nil, exampleEnglish: "How do you know that for sure?", exampleTranslation: "どうして確実にそれを知っていますか (Doushite kakujitsu ni sore wo shitte imasu ka)")
                ]),
                Unit(title: "Casual Slang & Particles", description: "Casual particles (Ne, Yo, Sa), slang words (Yabai, Majide, Naruhodo).", level: .expert, phrases: [
                    Phrase(english: "Seriously?! / Really?!", translation: "マジで？！ (Maji de?!)", romanization: nil, exampleEnglish: "Really?! That's incredible news!", exampleTranslation: "マジで？！それはすごいニュースだね！"),
                    Phrase(english: "Awesome! / Crazy!", translation: "ヤバい！ (Yabai!)", romanization: nil, exampleEnglish: "Look at that sunset, awesome!", exampleTranslation: "あの夕焼け見て、ヤバい！"),
                    Phrase(english: "I see! / Ah, makes sense", translation: "なるほど！ (Naruhodo!)", romanization: nil, exampleEnglish: "Ah I see, now I understand!", exampleTranslation: "なるほど！これで理解できました！"),
                    Phrase(english: "Anyway / By the way...", translation: "とにかく / ところで (Tonikaku / Tokorode)", romanization: nil, exampleEnglish: "By the way, did you eat lunch?", exampleTranslation: "ところで、お昼ごはん食べた？"),
                    Phrase(english: "It can't be helped / Shouganai", translation: "しょうがない (Shouganai)", romanization: nil, exampleEnglish: "It rained today, it can't be helped.", exampleTranslation: "今日は雨が降ったから、しょうがないね。"),
                    Phrase(english: "No way!", translation: "まさか (Masaka)", romanization: nil, exampleEnglish: "No way, that's incredible!", exampleTranslation: "まさか、信じられない (Masaka, shinjirarenai)"),
                    Phrase(english: "Cool", translation: "いいね (Ii ne)", romanization: nil, exampleEnglish: "That plan sounds cool.", exampleTranslation: "その計画いいね (Sono keikaku ii ne)"),
                    Phrase(english: "I'm dying of laughter", translation: "笑いすぎて死にそう (Warai sugite shini sou)", romanization: nil, exampleEnglish: "That joke, I'm dying of laughter!", exampleTranslation: "そのジョーク、笑いすぎて死にそう (Sono jooku, warai sugite shini sou)"),
                    Phrase(english: "It costs an arm and a leg", translation: "目玉が飛び出るほど高い (Medama ga tobideru hodo takai)", romanization: nil, exampleEnglish: "That car costs an arm and a leg.", exampleTranslation: "あの車は目玉が飛び出るほど高い (Ano kuruma wa medama ga tobideru hodo takai)")
                ]),
                Unit(title: "Polite Etiquette & Reverence", description: "Japanese bow angles, gift giving (Omiyage customs), and gratitude.", level: .beginner, phrases: [
                    Phrase(english: "A small souvenir for you", translation: "心ばかりの品です (Kokoro bakari no shina desu)", romanization: nil, exampleEnglish: "Please accept this, a small souvenir for you.", exampleTranslation: "どうぞお受け取りください、心ばかりの品です。"),
                    Phrase(english: "Please go ahead first", translation: "お先にお進みください (Osaki ni osusumi kudasai)", romanization: nil, exampleEnglish: "After you, please go ahead first.", exampleTranslation: "どうぞ、お先にお進みください。"),
                    Phrase(english: "Thank you for your warm kindness", translation: "ご親切にありがとうございます (Goshinsetsu ni arigatou gozaimasu)", romanization: nil, exampleEnglish: "Thank you for your warm kindness.", exampleTranslation: "ご親切にありがとうございます。"),
                    Phrase(english: "Pardon me for interrupting", translation: "お話し中に失礼します (Ohanashichuu ni shitsurei shimasu)", romanization: nil, exampleEnglish: "Pardon me for interrupting your talk.", exampleTranslation: "お話し中に失礼します。"),
                    Phrase(english: "I am always indebted to you", translation: "いつもお世話になっております (Itsumo osewa ni natte orimasu)", romanization: nil, exampleEnglish: "Greeting client: I am always indebted to you.", exampleTranslation: "いつも大変お世話になっております。"),
                    Phrase(english: "May I ask a question?", translation: "質問してもよろしいでしょうか (Shitsumon shite mo yoroshii deshou ka)", romanization: nil, exampleEnglish: "Excuse me, may I ask a question?", exampleTranslation: "失礼ですが、質問してもよろしいでしょうか (Shitsurei desu ga, shitsumon shite mo yoroshii deshou ka)"),
                    Phrase(english: "It would be a pleasure", translation: "喜んでお手伝いします (Yorokonde otetsudai shimasu)", romanization: nil, exampleEnglish: "It would be a pleasure to help.", exampleTranslation: "喜んでお手伝いさせていただきます (Yorokonde otetsudai sasete itadakimasu)"),
                    Phrase(english: "Please forgive me", translation: "お許しください (Oyurushi kudasai)", romanization: nil, exampleEnglish: "Please forgive me for the delay.", exampleTranslation: "遅れましたこと、お許しください (Okuremashita koto, oyurushi kudasai)"),
                    Phrase(english: "With your permission", translation: "失礼させていただきます (Shitsurei sasete itadakimasu)", romanization: nil, exampleEnglish: "With your permission, I'll take a seat.", exampleTranslation: "失礼させていただき、座らせていただきます (Shitsurei sasete itadaki, suwarasete itadakimasu)")
                ]),
                Unit(title: "Debating & Logic Structure", description: "Construct logical Japanese arguments with First, Second, Therefore.", level: .expert, phrases: [
                    Phrase(english: "First of all, the main reason is...", translation: "まず第一に、主な理由は... (Mazu daiichi ni, omo na riyuu wa...)", romanization: nil, exampleEnglish: "First of all, the main reason is safety.", exampleTranslation: "まず第一に、主な理由は安全性です。"),
                    Phrase(english: "On one hand..., on the other hand...", translation: "一方では...、他方では... (Ippou de wa..., tahou de wa...)", romanization: nil, exampleEnglish: "On one hand cost is low, on the other hand time is long.", exampleTranslation: "一方ではコストが低く、他方では時間がかかります。"),
                    Phrase(english: "According to survey data...", translation: "調査データによると... (Chousa deeta ni yoruto...)", romanization: nil, exampleEnglish: "According to survey data, customer satisfaction increased.", exampleTranslation: "調査データによると、顧客満足度が向上しました。"),
                    Phrase(english: "Therefore, in conclusion...", translation: "したがって、結論として... (Shitagatte, ketsuron to shite...)", romanization: nil, exampleEnglish: "Therefore, in conclusion, we propose this plan.", exampleTranslation: "したがって、結論としてこの案を提案します。"),
                    Phrase(english: "Counter argument", translation: "反論 (Hanron)", romanization: nil, exampleEnglish: "I respect that view, but I have a counter argument.", exampleTranslation: "その見解を尊重しますが、反論があります。"),
                    Phrase(english: "First of all", translation: "まず初めに (Mazu hajime ni)", romanization: nil, exampleEnglish: "First of all, let me clarify my position.", exampleTranslation: "まず初めに、私の立場を明確にさせてください (Mazu hajime ni, watashi no tachiba wo meikaku ni sasete kudasai)"),
                    Phrase(english: "On the other hand", translation: "一方で (Ippou de)", romanization: nil, exampleEnglish: "On the other hand, there are risks.", exampleTranslation: "一方で、リスクもあります (Ippou de, risuku mo arimasu)"),
                    Phrase(english: "The evidence suggests", translation: "証拠は示唆しています (Shouko wa shisa shite imasu)", romanization: nil, exampleEnglish: "The evidence suggests otherwise.", exampleTranslation: "証拠は反対のことを示唆しています (Shouko wa hantai no koto wo shisa shite imasu)"),
                    Phrase(english: "In conclusion", translation: "結論として (Ketsuron to shite)", romanization: nil, exampleEnglish: "In conclusion, I support the proposal.", exampleTranslation: "結論として、その提案を支持します (Ketsuron to shite, sono teian wo shiji shimasu)")
                ]),
                Unit(title: "Past Memories & Childhood", description: "Use past tense (~mashita / ~teta) to share childhood memories in Japan.", level: .intermediate, phrases: [
                    Phrase(english: "When I was a child...", translation: "子供のころ... (Kodomo no koro...)", romanization: nil, exampleEnglish: "When I was a child, I lived in Kyoto.", exampleTranslation: "子供のころ、京都に住んでいました。"),
                    Phrase(english: "I clearly remember that day", translation: "その日のことを鮮明に覚えています (Sono hi no koto o senmei ni oboete imasu)", romanization: nil, exampleEnglish: "I clearly remember that day.", exampleTranslation: "その日のことを今でも鮮明に覚えています。"),
                    Phrase(english: "We used to play together", translation: "よく一緒に遊んでいました (Yoku issho ni asonde imashita)", romanization: nil, exampleEnglish: "During summer, we used to play together.", exampleTranslation: "夏休みの間、よく一緒に遊んでいました。"),
                    Phrase(english: "Last year I visited Japan", translation: "昨年、日本を訪れました (Sakunen, Nihon o otozuremashita)", romanization: nil, exampleEnglish: "Last year I visited Japan for the first time.", exampleTranslation: "昨年、初めて日本を訪れました。"),
                    Phrase(english: "Times have changed", translation: "時代が変わりました (Jidai ga kawarimashita)", romanization: nil, exampleEnglish: "Since then, times have changed greatly.", exampleTranslation: "それから時代が大きく変わりました。"),
                    Phrase(english: "When I was a child", translation: "子供の頃 (Kodomo no koro)", romanization: nil, exampleEnglish: "When I was a child, we lived in Tokyo.", exampleTranslation: "子供の頃、私たちは東京に住んでいました (Kodomo no koro, watashitachi wa Toukyou ni sunde imashita)"),
                    Phrase(english: "That was ten years ago", translation: "それは十年前のことです (Sore wa juunen mae no koto desu)", romanization: nil, exampleEnglish: "That trip was ten years ago now.", exampleTranslation: "あの旅行はもう十年前のことです (Ano ryokou wa mou juunen mae no koto desu)"),
                    Phrase(english: "I used to play soccer", translation: "昔サッカーをしていました (Mukashi sakkaa wo shite imashita)", romanization: nil, exampleEnglish: "I used to play soccer every Saturday.", exampleTranslation: "毎週土曜日にサッカーをしていました (Maishuu doyoubi ni sakkaa wo shite imashita)"),
                    Phrase(english: "I remember it well", translation: "よく覚えています (Yoku oboete imasu)", romanization: nil, exampleEnglish: "I remember that summer very well.", exampleTranslation: "あの夏のことをよく覚えています (Ano natsu no koto wo yoku oboete imasu)")
                ]),
                Unit(title: "Future Dreams & Goals", description: "Future intentions (~Tsumori / ~Yotei) for career and learning goals.", level: .intermediate, phrases: [
                    Phrase(english: "I plan to live in Japan", translation: "日本に住む予定です (Nihon ni sumu yotei desu)", romanization: nil, exampleEnglish: "Next year, I plan to live in Japan.", exampleTranslation: "来年、日本に住む予定です。"),
                    Phrase(english: "My goal is to speak fluent Japanese", translation: "私の目標は日本語をペラペラ話すことです (Watashi no mokuhyou wa nihongo o perapera hanasu koto desu)", romanization: nil, exampleEnglish: "My goal is to speak fluent Japanese this year.", exampleTranslation: "私の目標は今年日本語をペラペラ話すことです。"),
                    Phrase(english: "I intend to start a company", translation: "会社を設立するつもりです (Kaisha o seritsu suru tsumori desu)", romanization: nil, exampleEnglish: "In future, I intend to start a tech company.", exampleTranslation: "将来、IT会社を設立するつもりです。"),
